#ifndef KATAGO_HUMANRKNNBACKEND_H_
#define KATAGO_HUMANRKNNBACKEND_H_
#include <memory>
#include <string>

// True only while the 9x9 Human b18 RKNN runner is actually initialized
// and has not been reset by an NPU error or native CPU parity mismatch.
bool isKataGoHumanRknnActive();

// Optional, independently compiled b18 Human SL RKNN bridge (9x9 only).
// All inputs are generated by the existing KataGo NN + SGFMetadata encoder.
// Does not replace or modify the existing g170 10b RKNN runner.
class KataGoHumanRknnRunner {
 public:
  explicit KataGoHumanRknnRunner(const std::string& modelPath, int boardSize);
  ~KataGoHumanRknnRunner();
  KataGoHumanRknnRunner(const KataGoHumanRknnRunner&) = delete;
  KataGoHumanRknnRunner& operator=(const KataGoHumanRknnRunner&) = delete;
  bool ready() const;
  void infer(const float* spatialNHWC, const float* global,
             const float* meta192, float* policyPass2,
             float* policyNHWC2, float* value3,
             float* score6, float* ownership);
 private:
  struct Impl;
  std::unique_ptr<Impl> impl_;
};
#endif
